-- Additive sales workspace. Existing customers, prices and accounting are not imported.
CREATE TABLE IF NOT EXISTS scm_customers(business_id TEXT NOT NULL,contact_id TEXT NOT NULL,stopped INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(business_id,contact_id),FOREIGN KEY(business_id,contact_id) REFERENCES portfolio_contacts(business_id,id));
CREATE TABLE IF NOT EXISTS scm_people(id TEXT PRIMARY KEY,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS scm_identity_links(id TEXT PRIMARY KEY,person_id TEXT NOT NULL REFERENCES scm_people(id),business_id TEXT NOT NULL,contact_id TEXT NOT NULL,active INTEGER NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(business_id,contact_id) REFERENCES portfolio_contacts(business_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS scm_identity_active ON scm_identity_links(business_id,contact_id) WHERE active=1;
CREATE TABLE IF NOT EXISTS scm_tax(business_id TEXT PRIMARY KEY REFERENCES portfolio_businesses(id),tax_type TEXT NOT NULL,rate TEXT NOT NULL,rounding TEXT NOT NULL,revision INTEGER NOT NULL,confirmed INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS scm_rates(business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),id TEXT NOT NULL,label TEXT NOT NULL,unit_yen TEXT,conditions TEXT NOT NULL,confirmed INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(business_id,id));
CREATE TABLE IF NOT EXISTS scm_deals(business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),id TEXT NOT NULL,entry_key TEXT NOT NULL,contact_id TEXT NOT NULL,subject TEXT NOT NULL,inquiry TEXT NOT NULL,stage TEXT NOT NULL,state TEXT NOT NULL,mode TEXT NOT NULL,agent TEXT,human_owner TEXT,next_day TEXT,last_response_at TEXT,revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,PRIMARY KEY(business_id,id),UNIQUE(business_id,entry_key),FOREIGN KEY(business_id,contact_id) REFERENCES portfolio_contacts(business_id,id));
CREATE TABLE IF NOT EXISTS scm_notes(business_id TEXT NOT NULL,deal_id TEXT NOT NULL,id TEXT NOT NULL,body TEXT NOT NULL,mode TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(business_id,id),FOREIGN KEY(business_id,deal_id) REFERENCES scm_deals(business_id,id));
CREATE TABLE IF NOT EXISTS scm_quotes(business_id TEXT NOT NULL,deal_id TEXT NOT NULL,id TEXT NOT NULL,version INTEGER NOT NULL,previous_id TEXT,body TEXT NOT NULL,digest TEXT NOT NULL,expires_day TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(business_id,id),UNIQUE(business_id,deal_id,version),FOREIGN KEY(business_id,deal_id) REFERENCES scm_deals(business_id,id),FOREIGN KEY(business_id,previous_id) REFERENCES scm_quotes(business_id,id));
CREATE TABLE IF NOT EXISTS scm_bookings(business_id TEXT NOT NULL,deal_id TEXT NOT NULL,id TEXT NOT NULL,kind TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT NOT NULL,case_id TEXT,status TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(business_id,id),FOREIGN KEY(business_id,deal_id) REFERENCES scm_deals(business_id,id),FOREIGN KEY(business_id,case_id) REFERENCES portfolio_cases(business_id,id));
CREATE TABLE IF NOT EXISTS scm_actions(business_id TEXT NOT NULL,deal_id TEXT NOT NULL,id TEXT NOT NULL,entry_key TEXT NOT NULL,kind TEXT NOT NULL,quote_id TEXT,booking_id TEXT,body TEXT NOT NULL,snapshot TEXT NOT NULL,status TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_at TEXT,evidence TEXT,created_at TEXT NOT NULL,recorded_at TEXT,PRIMARY KEY(business_id,id),UNIQUE(business_id,entry_key),UNIQUE(business_id,deal_id,kind,snapshot),FOREIGN KEY(business_id,deal_id) REFERENCES scm_deals(business_id,id),FOREIGN KEY(business_id,quote_id) REFERENCES scm_quotes(business_id,id),FOREIGN KEY(business_id,booking_id) REFERENCES scm_bookings(business_id,id));
CREATE TABLE IF NOT EXISTS scm_attempts(id TEXT PRIMARY KEY,business_id TEXT NOT NULL,action_id TEXT NOT NULL,outcome TEXT NOT NULL,mode TEXT NOT NULL,deadline TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(business_id,action_id) REFERENCES scm_actions(business_id,id));
CREATE TABLE IF NOT EXISTS scm_invoices(business_id TEXT NOT NULL,deal_id TEXT NOT NULL,id TEXT NOT NULL,quote_id TEXT NOT NULL,net_yen INTEGER NOT NULL,tax_yen INTEGER NOT NULL,gross_yen INTEGER NOT NULL,mode TEXT NOT NULL,action_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(business_id,id),UNIQUE(business_id,action_id),FOREIGN KEY(business_id,deal_id) REFERENCES scm_deals(business_id,id),FOREIGN KEY(business_id,quote_id) REFERENCES scm_quotes(business_id,id));
CREATE TABLE IF NOT EXISTS scm_cash(business_id TEXT NOT NULL,deal_id TEXT NOT NULL,id TEXT NOT NULL,invoice_id TEXT NOT NULL,kind TEXT NOT NULL,amount_yen INTEGER NOT NULL,mode TEXT NOT NULL,action_id TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(business_id,id),UNIQUE(business_id,action_id),FOREIGN KEY(business_id,invoice_id) REFERENCES scm_invoices(business_id,id),FOREIGN KEY(business_id,deal_id) REFERENCES scm_deals(business_id,id));
CREATE TABLE IF NOT EXISTS scm_credits(business_id TEXT NOT NULL,id TEXT NOT NULL,invoice_id TEXT NOT NULL,action_id TEXT NOT NULL,mode TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(business_id,id),UNIQUE(business_id,invoice_id),FOREIGN KEY(business_id,invoice_id) REFERENCES scm_invoices(business_id,id));
CREATE TABLE IF NOT EXISTS scm_work(task_id TEXT PRIMARY KEY REFERENCES tasks(id),business_id TEXT NOT NULL,deal_id TEXT NOT NULL,activity TEXT NOT NULL,FOREIGN KEY(business_id,deal_id) REFERENCES scm_deals(business_id,id));
CREATE TABLE IF NOT EXISTS scm_role_requests(id TEXT PRIMARY KEY,business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),work TEXT NOT NULL,proposed_agent TEXT,reason TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS scm_seminars(business_id TEXT NOT NULL,deal_id TEXT NOT NULL,seminar_id TEXT NOT NULL REFERENCES seminars(id),participant_username TEXT REFERENCES seminar_registrations(username),created_at TEXT NOT NULL,PRIMARY KEY(business_id,deal_id,seminar_id),FOREIGN KEY(business_id,deal_id) REFERENCES scm_deals(business_id,id));
CREATE TABLE IF NOT EXISTS scm_events(id INTEGER PRIMARY KEY,business_id TEXT NOT NULL REFERENCES portfolio_businesses(id),deal_id TEXT,actor TEXT NOT NULL,event TEXT NOT NULL,ref TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
